// kittu-compat:file
// Generated by scripts/rebrand-kittu.mjs; legacy names are intentional.
import { mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
	defaultKittuHome,
	hookScriptCandidates,
} from "../src/legacy-compat.js";

describe("defaultKittuHome", () => {
	let home: string;

	beforeEach(() => {
		home = mkdtempSync(join(tmpdir(), "kittu-home-"));
	});

	afterEach(() => {
		rmSync(home, { recursive: true, force: true });
	});

	it("returns ~/.kittu on a fresh machine", () => {
		expect(defaultKittuHome(home)).toBe(join(home, ".kittu"));
	});

	it("falls back to ~/.cyrus when only the legacy home exists", () => {
		mkdirSync(join(home, ".cyrus"));
		expect(defaultKittuHome(home)).toBe(join(home, ".cyrus"));
	});

	it("prefers ~/.kittu when both exist", () => {
		mkdirSync(join(home, ".cyrus"));
		mkdirSync(join(home, ".kittu"));
		expect(defaultKittuHome(home)).toBe(join(home, ".kittu"));
	});
});

describe("hookScriptCandidates", () => {
	it("lists kittu-* before the legacy cyrus-* names", () => {
		const files = hookScriptCandidates("setup").map((c) => c.file);
		expect(files).toEqual([
			"kittu-setup.sh",
			"kittu-setup.ps1",
			"kittu-setup.cmd",
			"kittu-setup.bat",
			"cyrus-setup.sh",
			"cyrus-setup.ps1",
			"cyrus-setup.cmd",
			"cyrus-setup.bat",
		]);
	});

	it("tags platforms", () => {
		const byFile = Object.fromEntries(
			hookScriptCandidates("teardown").map((c) => [c.file, c.platform]),
		);
		expect(byFile["kittu-teardown.sh"]).toBe("unix");
		expect(byFile["cyrus-teardown.ps1"]).toBe("windows");
	});
});
